//! KNIRV WebAssembly modules: manifest, verification and (optionally) bytes.
//!
//! The manifest (`wasm-modules/manifest.json`) is generated by the SDK build
//! from `wasm-modules/modules.json` plus the built bytes, and is the one record
//! of each module's digest, length, kind, ABI and capabilities. It is small, so
//! digests and [`WasmModule::verify`] work everywhere. The module bytes
//! (about 0.8 MB) are embedded only with the `embedded-modules` feature, which
//! native tools such as `knirv-sdk extract` enable; WebAssembly hosts fetch
//! them from the release URL instead.

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
#[cfg(all(not(target_arch = "wasm32"), feature = "filesystem", feature = "embedded-modules"))]
use std::fs;
use std::{fmt, io, path::Path, sync::OnceLock};

#[derive(Clone, Debug, Deserialize, Serialize, PartialEq, Eq)]
pub struct WasmModuleMetadata {
    pub id: String,
    pub artifact_version: String,
    pub module_kind: String,
    pub abi_version: u32,
    pub byte_length: usize,
    pub sha256: String,
    pub capabilities: Vec<String>,
}

#[derive(Deserialize)]
struct Manifest {
    modules: Vec<WasmModuleMetadata>,
}

fn manifest() -> &'static [WasmModuleMetadata] {
    static MANIFEST: OnceLock<Vec<WasmModuleMetadata>> = OnceLock::new();
    MANIFEST.get_or_init(|| {
        serde_json::from_str::<Manifest>(include_str!("../wasm-modules/manifest.json"))
            .expect("wasm-modules/manifest.json is generated by the SDK build and is valid")
            .modules
    })
}

/// A WebAssembly module packaged with the KNIRV SDK.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum WasmModule {
    ControllerRelay,
    CryptoCore,
    ProofVerifier,
}

impl WasmModule {
    pub const ALL: [Self; 3] = [Self::ControllerRelay, Self::CryptoCore, Self::ProofVerifier];

    /// Stable module identifier for configuration, CLI, and host integrations.
    pub const fn id(self) -> &'static str {
        match self {
            Self::ControllerRelay => "controller-relay",
            Self::CryptoCore => "crypto-core",
            Self::ProofVerifier => "proof-verifier",
        }
    }

    pub const fn description(self) -> &'static str {
        match self {
            Self::ControllerRelay => "KNIRV controller relay envelope module",
            Self::CryptoCore => "KNIRV SDK vault crypto module",
            Self::ProofVerifier => "KNIRV proof event-log verifier module",
        }
    }

    /// Embedded, immutable module bytes. This is zero-copy. Only with the
    /// `embedded-modules` feature.
    #[cfg(feature = "embedded-modules")]
    pub const fn bytes(self) -> &'static [u8] {
        match self {
            Self::ControllerRelay => include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/wasm-modules/assets/controller-relay.wasm"
            )),
            Self::CryptoCore => include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/wasm-modules/assets/crypto-core.wasm"
            )),
            Self::ProofVerifier => include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/wasm-modules/assets/proof-verifier.wasm"
            )),
        }
    }

    /// SHA-256 of the exact artifact, used to pin host-side loading.
    pub fn sha256(self) -> &'static str {
        &self.entry().sha256
    }

    fn entry(self) -> &'static WasmModuleMetadata {
        manifest()
            .iter()
            .find(|entry| entry.id == self.id())
            .expect("every module is in the generated manifest")
    }

    /// Versioned metadata for safe consumption outside this crate.
    pub fn metadata(self) -> WasmModuleMetadata {
        self.entry().clone()
    }

    /// Checks immutable bytes against the SDK's manifest.
    pub fn verify(self, bytes: &[u8]) -> Result<(), String> {
        if !bytes.starts_with(b"\0asm") {
            return Err("not a WebAssembly binary".into());
        }
        if bytes.len() != self.entry().byte_length {
            return Err(format!("unexpected byte length: {}", bytes.len()));
        }
        if hex::encode(Sha256::digest(bytes)) != self.sha256() {
            return Err("SHA-256 digest does not match manifest".into());
        }
        let exports = wasm_exports(bytes)?;
        for expected in self.required_exports() {
            if !exports.iter().any(|actual| actual == expected) {
                return Err(format!(
                    "missing required {} ABI export: {expected}",
                    self.entry().module_kind
                ));
            }
        }
        Ok(())
    }

    /// The exports that define this module's ABI. They are verified in addition
    /// to the digest, making an accidental manifest/module mismatch visible.
    pub const fn required_exports(self) -> &'static [&'static str] {
        match self {
            Self::ControllerRelay => &["abi_version", "module_kind", "invoke"],
            Self::CryptoCore => &[
                "abi_version",
                "module_kind",
                "self_test",
                "crypto_protocol_version",
                "allocate",
                "deallocate",
                "invoke",
                "result_pointer",
                "result_length",
                "free_result",
                "zeroize",
            ],
            Self::ProofVerifier => &["abi_version", "module_kind", "invoke"],
        }
    }

    pub fn parse(value: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|module| module.id() == value)
    }

    /// Writes this module to `destination`. The destination is fully owned by
    /// the caller; the SDK never creates or mutates other files.
    #[cfg(all(not(target_arch = "wasm32"), feature = "filesystem", feature = "embedded-modules"))]
    pub fn materialize(self, destination: impl AsRef<Path>) -> io::Result<()> {
        fs::write(destination, self.bytes())
    }

    #[cfg(not(all(not(target_arch = "wasm32"), feature = "filesystem", feature = "embedded-modules")))]
    pub fn materialize(self, _destination: impl AsRef<Path>) -> io::Result<()> {
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "WASM module materialization requires the native `filesystem` and `embedded-modules` features",
        ))
    }
}

fn wasm_exports(bytes: &[u8]) -> Result<Vec<String>, String> {
    if bytes.len() < 8 || &bytes[..4] != b"\0asm" {
        return Err("not a WebAssembly binary".into());
    }
    let mut pos = 8;
    while pos < bytes.len() {
        let id = bytes[pos];
        pos += 1;
        let (length, used) = read_leb(&bytes[pos..])?;
        pos += used;
        let end = pos
            .checked_add(length as usize)
            .ok_or("invalid WebAssembly section length")?;
        if end > bytes.len() {
            return Err("truncated WebAssembly section".into());
        }
        if id == 7 {
            let section = &bytes[pos..end];
            let (count, mut offset) = read_leb(section)?;
            let mut names = Vec::with_capacity(count as usize);
            for _ in 0..count {
                let (name_length, used) = read_leb(&section[offset..])?;
                offset += used;
                let name_end = offset
                    .checked_add(name_length as usize)
                    .ok_or("invalid export name length")?;
                if name_end >= section.len() {
                    return Err("truncated WebAssembly export".into());
                }
                let name = std::str::from_utf8(&section[offset..name_end])
                    .map_err(|_| "non-UTF-8 WebAssembly export")?
                    .to_owned();
                offset = name_end;
                offset += 1; // export kind
                let (_, used) = read_leb(&section[offset..])?;
                offset += used; // index
                names.push(name);
            }
            return Ok(names);
        }
        pos = end;
    }
    Err("WebAssembly module has no export section".into())
}
fn read_leb(input: &[u8]) -> Result<(u32, usize), String> {
    let mut value = 0u32;
    for (index, byte) in input.iter().copied().enumerate().take(5) {
        value |= ((byte & 0x7f) as u32) << (7 * index);
        if byte & 0x80 == 0 {
            return Ok((value, index + 1));
        }
    }
    Err("invalid unsigned LEB128 value".into())
}

impl fmt::Display for WasmModule {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.id())
    }
}

/// Returns an embedded module by stable identifier.
pub fn wasm_module(id: &str) -> Option<WasmModule> {
    WasmModule::parse(id)
}

/// Materializes an embedded module by stable identifier.
pub fn materialize_wasm_module(id: &str, destination: impl AsRef<Path>) -> io::Result<()> {
    let module = WasmModule::parse(id).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("unknown KNIRV WASM module: {id}"),
        )
    })?;
    module.materialize(destination)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[cfg(feature = "embedded-modules")]
    #[test]
    fn every_embedded_module_has_the_pinned_digest() {
        for module in WasmModule::ALL {
            assert!(module.verify(module.bytes()).is_ok(), "{module}");
        }
    }

    #[test]
    fn the_manifest_describes_every_module() {
        for module in WasmModule::ALL {
            let meta = module.metadata();
            assert_eq!(meta.id, module.id());
            assert_eq!(meta.sha256.len(), 64);
            assert!(meta.byte_length > 0);
        }
    }

    #[test]
    fn verification_rejects_other_bytes_without_needing_embedded_ones() {
        assert!(WasmModule::CryptoCore.verify(b"\0asm\x01\0\0\0").is_err());
        assert!(WasmModule::CryptoCore.verify(b"nope").is_err());
    }

    #[test]
    fn modules_are_found_by_their_stable_identifiers() {
        assert_eq!(wasm_module("crypto-core"), Some(WasmModule::CryptoCore));
        assert_eq!(wasm_module("unknown"), None);
    }
}
